CREATE TABLE finance_transaction_template (id UUID PRIMARY KEY DEFAULT uuid_v7(),ledger_id UUID NOT NULL,owner_id UUID NOT NULL,name VARCHAR(256) NOT NULL,type VARCHAR(24) NOT NULL,account_id UUID NOT NULL,target_account_id UUID,amount NUMERIC(19,4),currency CHAR(3) NOT NULL,category_id UUID,payee VARCHAR(256),note TEXT,archived BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),version BIGINT NOT NULL DEFAULT 0,CHECK(type IN ('INCOME','EXPENSE','TRANSFER','ADJUSTMENT')),CHECK(amount IS NULL OR amount>=0),FOREIGN KEY(ledger_id) REFERENCES finance_ledger(id),FOREIGN KEY(account_id) REFERENCES finance_account(id),FOREIGN KEY(target_account_id) REFERENCES finance_account(id),UNIQUE(ledger_id,name)); CREATE INDEX idx_finance_template ON finance_transaction_template(ledger_id,owner_id,archived,name);
